function esc(s=''){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
function escAttr(s=''){return esc(s);}
function cleanHttpUrl(value=''){try{const url=new URL(String(value||'').trim());return ['http:','https:'].includes(url.protocol)?url.toString():'';}catch{return'';}}

function parseSourcesText(text=''){
  const out=[];const seen=new Set();
  for(const raw of String(text).split('\n')){const line=raw.trim();if(!line)continue;let source={};if(line.startsWith('{')){try{source=JSON.parse(line);}catch{continue;}}else{const parts=line.split('|').map(x=>x.trim());const [title='',url='',publisher='',date='']=parts;source={title,url,publisher,date,origin:'human',verification:'verified'};}const title=String(source.title||'').trim(),url=cleanHttpUrl(source.url);if(!title||!url||seen.has(url))continue;seen.add(url);out.push({...source,title,url,origin:source.origin==='source-agent'?'source-agent':'human',verification:['candidate','verified','rejected'].includes(source.verification)?source.verification:(source.origin==='source-agent'?'candidate':'verified')});}
  return out;
}
function formatSourcesText(items=[]){return (Array.isArray(items)?items:[]).map(x=>JSON.stringify({id:x.id||'',title:x.title||'',url:x.url||'',publisher:x.publisher||'',date:x.date||'',origin:x.origin||'human',verification:x.verification||'verified',retrievedAt:x.retrievedAt||'',why:x.why||'',supports:x.supports||'',challenges:x.challenges||''})).join('\n');}
function parseClaimsText(text=''){
  return String(text).split('\n').map(raw=>{const line=raw.trim();if(!line)return null;const parts=line.split('|').map(x=>x.trim());const status=['supported','interpretation','open'].includes(parts[0])?parts[0]:'open';const text=parts[1]||'';const evidence=(parts[2]||'').split(',').map(x=>x.trim()).filter(Boolean);const note=parts.slice(3).join(' | ').trim();return text?{status,text,evidence,note}:null;}).filter(Boolean);
}
function formatClaimsText(items=[]){return (Array.isArray(items)?items:[]).map(x=>[x.status||'open',x.text||'',(x.evidence||[]).join(', '),x.note||''].join(' | ').replace(/(?:\s*\|\s*)+$/,'')).join('\n');}
function parseJsonArray(text=''){try{const v=JSON.parse(String(text||'[]'));return Array.isArray(v)?v:[];}catch{return [];}}
function selectedCitationMode(){return els.citationModeChecks.find(x=>x.checked)?.value||'inline';}
function setCitationMode(value='inline'){const mode=['inline','sources','both'].includes(value)?value:'inline';els.citationModeChecks.forEach(x=>x.checked=x.value===mode);}
function applyCitationPlacements(body='',placements=[]){let out=String(body||'');for(const p of Array.isArray(placements)?placements:[]){const quote=String(p.quote||''),anchor=String(p.anchorText||''),url=String(p.evidenceUrl||'');if(!quote||!anchor||!url||!quote.includes(anchor))continue;const first=out.indexOf(quote);if(first<0||out.indexOf(quote,first+quote.length)>=0)continue;const linked=quote.replace(anchor,`[${anchor}](${url})`);out=out.slice(0,first)+linked+out.slice(first+quote.length);}return out;}
function chartSvg(chart={},compact=false){const series=Array.isArray(chart.series)?chart.series:[];if(series.length<2)return '';const w=compact?520:760,h=compact?240:320,pad={l:54,r:20,t:34,b:64};const vals=series.map(x=>Number(x.value)).filter(Number.isFinite);if(vals.length<2)return '';let min=Math.min(0,...vals),max=Math.max(0,...vals);if(min===max){min-=1;max+=1;}const y=v=>pad.t+(max-v)/(max-min)*(h-pad.t-pad.b),base=y(0),inner=w-pad.l-pad.r;const escSvg=s=>esc(String(s));let marks='';if(chart.type==='line'){const pts=series.map((p,i)=>`${pad.l+(i/(series.length-1))*inner},${y(Number(p.value))}`).join(' ');marks=`<polyline points="${pts}" fill="none" stroke="currentColor" stroke-width="2"/>`+series.map((p,i)=>`<circle cx="${pad.l+(i/(series.length-1))*inner}" cy="${y(Number(p.value))}" r="4" fill="currentColor"/>`).join('');}else{const gap=inner/series.length,bw=Math.max(8,gap*.58);marks=series.map((p,i)=>{const yy=y(Number(p.value)),x=pad.l+i*gap+(gap-bw)/2,top=Math.min(yy,base),hh=Math.max(1,Math.abs(base-yy));return `<rect x="${x}" y="${top}" width="${bw}" height="${hh}" rx="3" fill="currentColor" opacity=".72"/>`;}).join('');}const labels=series.map((p,i)=>{const x=pad.l+(i+(chart.type==='line'?0:0.5))*inner/(chart.type==='line'?Math.max(1,series.length-1):series.length);return `<text x="${x}" y="${h-26}" text-anchor="middle">${escSvg(String(p.label).slice(0,16))}</text>`;}).join('');return `<svg viewBox="0 0 ${w} ${h}" role="img" aria-label="${escAttr(chart.title||'Kaavio')}"><line x1="${pad.l}" y1="${base}" x2="${w-pad.r}" y2="${base}" stroke="currentColor" opacity=".22"/>${marks}${labels}</svg>`;}
function renderVisualizationReview(){if(!els.visualizationReview)return;const charts=parseJsonArray(els.visualizations?.value);if(!charts.length){els.visualizationReview.innerHTML='<p class="source-empty">Ei hyväksyttyjä kaavioita. Aja tarvittaessa Visualisointivahti ja tarkista ehdotus.</p>';return;}els.visualizationReview.innerHTML=charts.map((c,i)=>`<article class="visualization-card"><div><span>HYVÄKSYTTY · ${esc((c.type||'bar').toUpperCase())}</span><h4>${esc(c.title||`Kaavio ${i+1}`)}</h4>${c.caption?`<p>${esc(c.caption)}</p>`:''}</div>${chartSvg(c,true)}<small>${(c.series||[]).length} datapistettä · jokaisella evidenssijälki</small><button type="button" class="ghost" data-viz-remove="${i}">Poista</button></article>`).join('');}
function slugify(s=''){return String(s).normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-+|-+$/g,'').slice(0,90);}
function inline(s=''){let x=esc(s);x=x.replace(/`([^`]+)`/g,'<code>$1</code>').replace(/\[([^\]]+)\]\((https?:\/\/[^\s)]+|\/[^\s)]*)\)/g,'<a href="$2" target="_blank" rel="noopener noreferrer">$1</a>').replace(/\*\*([^*]+)\*\*/g,'<strong>$1</strong>').replace(/(^|[^*])\*([^*]+)\*/g,'$1<em>$2</em>');return x;}
function imageMarkup(line){
  const m=String(line).match(/^!\[([^\]]*)\]\((https?:\/\/[^\s)]+|\/[^\s)]+)(?:\s+"([^"]*)")?\)$/);
  if(!m)return null;
  const [,alt,url,caption='']=m;const src=state.mediaPreviews[url]||url;
  return `<figure class="md-image"><img src="${escAttr(src)}" alt="${escAttr(alt)}" loading="lazy">${caption?`<figcaption>${esc(caption)}</figcaption>`:''}</figure>`;
}
function markdown(md=''){
  const lines=String(md).replace(/\r\n/g,'\n').split('\n'),out=[];let para=[],list=null,code=false,codeLines=[];
  const fp=()=>{if(para.length){out.push(`<p>${inline(para.join(' '))}</p>`);para=[]}};
  const fl=()=>{if(list){out.push(`<${list.t}>${list.a.map(v=>`<li>${inline(v)}</li>`).join('')}</${list.t}>`);list=null}};
  const fc=()=>{if(code){out.push(`<pre><code>${esc(codeLines.join('\n'))}</code></pre>`);code=false;codeLines=[]}};
  for(const line of lines){
    if(line.startsWith('```')){fp();fl();if(code)fc();else code=true;continue}
    if(code){codeLines.push(line);continue}
    const img=imageMarkup(line.trim());if(img){fp();fl();out.push(img);continue}
    const h=line.match(/^(#{1,3})\s+(.+)/);if(h){fp();fl();out.push(`<h${h[1].length}>${inline(h[2])}</h${h[1].length}>`);continue}
    if(/^>\s?/.test(line)){fp();fl();out.push(`<blockquote>${inline(line.replace(/^>\s?/,''))}</blockquote>`);continue}
    const ul=line.match(/^[-*]\s+(.+)/);const ol=line.match(/^\d+\.\s+(.+)/);if(ul||ol){fp();const t=ul?'ul':'ol';if(!list||list.t!==t){fl();list={t,a:[]}}list.a.push((ul||ol)[1]);continue}
    if(/^---+$/.test(line.trim())){fp();fl();out.push('<hr>');continue}
    if(!line.trim()){fp();fl();continue}
    para.push(line.trim())
  }
  fp();fl();fc();return out.join('');
}

