function renderLiveLink(){const p=currentForm(Boolean(state.current?.draft));const slug=p.slug||slugify(p.title);const path=publicPath(p);els.publicUrl.textContent=`${PUBLIC_ORIGIN}${path}`;const savedSlug=state.current?.slug||slugify(state.current?.title||'');const isPublished=Boolean(state.current?.path&&state.current?.draft===false);const isSavedUrl=Boolean(isPublished&&slug&&slug===savedSlug&&p.lang===(state.current?.lang||p.lang));if(isSavedUrl){els.publicUrlHint.textContent='Julkaistu. Tämä on nykyinen julkinen osoite.';els.live.href=`${PUBLIC_ORIGIN}${path}`;els.live.hidden=false;}else{els.live.hidden=true;if(isPublished&&slug){els.publicUrlHint.textContent='URL on muuttunut. Julkaise muutokset, jotta uusi osoite aktivoituu.';}else if(state.current?.path&&state.current?.draft){els.publicUrlHint.textContent='Luonnos. Osoite aktivoituu julkaistaessa.';}else{els.publicUrlHint.textContent='URL muodostuu otsikosta tai URL-tunnuksesta.';}}}
function evidenceSnapshot(){const sources=parseSourcesText(els.sources?.value||''),claims=parseClaimsText(els.claims?.value||''),verified=new Set(sources.filter(source=>source.verification==='verified').map(source=>source.url));const blockers=[];for(const source of sources)if(source.verification!=='verified')blockers.push({type:'source',text:`Lähde odottaa tarkistusta: ${source.title}`});claims.forEach((claim,index)=>{if(claim.status==='supported'&&!claim.evidence.some(url=>verified.has(url)))blockers.push({type:'claim',index,text:`Tuettu väite ${index+1} tarvitsee tarkistetun lähteen.`});});const readyClaims=claims.filter(claim=>claim.status!=='supported'||claim.evidence.some(url=>verified.has(url))).length;return{sources,claims,verified,blockers,readyClaims};}
function renderEvidenceSummary(){const data=evidenceSnapshot();if(els.evidenceReadiness){const checked=data.sources.filter(source=>source.verification==='verified').length;els.evidenceReadiness.innerHTML=`<div><span>Lähteet tarkistettu</span><strong>${checked}/${data.sources.length}</strong></div><div><span>Väitteet julkaisuvalmiina</span><strong>${data.readyClaims}/${data.claims.length}</strong></div><div><span>Julkaisuportti</span><strong data-state="${data.blockers.length?'blocked':'ready'}">${data.blockers.length?`${data.blockers.length} estettä`:'Valmis'}</strong></div>`;}if(els.evidenceBlockers){els.evidenceBlockers.hidden=!data.blockers.length;els.evidenceBlockers.innerHTML=data.blockers.length?`<strong>Korjaa ennen julkaisua</strong><ul>${data.blockers.map(item=>`<li>${esc(item.text)}</li>`).join('')}</ul>`:'';}return data;}
function renderSourceReview(){if(!els.sourceReview)return;const {sources}=evidenceSnapshot();if(!sources.length){els.sourceReview.innerHTML='<p class="source-empty">Ei lähteitä. Lisää ensimmäinen lähde yllä tai aja Lähdeagentti.</p>';return;}els.sourceReview.innerHTML=sources.map((source,index)=>{const status=source.verification||'verified';const label=status==='verified'?'Tarkistettu':status==='rejected'?'Hylätty':'Ehdokas';return `<article class="source-card" data-source-status="${escAttr(status)}"><div class="source-card-head"><span class="source-state">${label}</span><span>L${index+1} · ${source.origin==='source-agent'?'Agenttihaku':'Ihmisen lisäämä'}</span></div><h4>${esc(source.title)}</h4><p class="source-url">${esc(source.url)}</p>${source.publisher||source.date?`<p>${esc([source.publisher,source.date].filter(Boolean).join(' · '))}</p>`:''}${source.why?`<p><strong>Miksi:</strong> ${esc(source.why)}</p>`:''}${source.supports?`<p><strong>Tukee:</strong> ${esc(source.supports)}</p>`:''}${source.challenges?`<p><strong>Haastaa:</strong> ${esc(source.challenges)}</p>`:''}<div class="source-actions"><a href="${escAttr(source.url)}" target="_blank" rel="noopener noreferrer">Avaa lähde ↗</a>${status!=='verified'?`<button type="button" data-source-action="verify" data-source-index="${index}">Merkitse tarkistetuksi</button>`:''}${status==='verified'&&source.origin==='source-agent'?`<button type="button" class="ghost" data-source-action="candidate" data-source-index="${index}">Palauta ehdokkaaksi</button>`:''}<button type="button" class="ghost" data-source-action="remove" data-source-index="${index}">Poista</button></div></article>`;}).join('');}
function renderClaimReview(){if(!els.claimReview)return;const data=evidenceSnapshot();if(!data.claims.length){els.claimReview.innerHTML='<p class="source-empty">Ei väitteitä. Lisää väite korttina tai aja Väitevahti.</p>';return;}els.claimReview.innerHTML=data.claims.map((claim,index)=>{const missing=claim.status==='supported'&&!claim.evidence.some(url=>data.verified.has(url));const sourceChoices=data.sources.length?data.sources.map((source,sourceIndex)=>{const checked=claim.evidence.includes(source.url),candidate=source.verification!=='verified',disabled=claim.status==='supported'&&candidate;return `<label class="claim-source-option${candidate?' candidate':''}${disabled?' disabled':''}"><input type="checkbox" data-claim-source="${index}" data-source-url="${escAttr(source.url)}" ${checked?'checked':''} ${disabled?'disabled':''}><span><strong>L${sourceIndex+1} · ${esc(source.title)}</strong><small>${source.verification==='verified'?'Tarkistettu':'Ehdokas'}${disabled?' · ei kelpaa tuetun väitteen evidenssiksi':''}</small></span></label>`;}).join(''):'<p class="field-help">Lisää ensin lähde.</p>';return `<article class="claim-card${missing?' has-blocker':''}" data-claim-index="${index}"><div class="claim-card-head"><span>VÄITE ${index+1}</span><select aria-label="Väitteen tila" data-claim-field="status" data-claim-index="${index}"><option value="supported" ${claim.status==='supported'?'selected':''}>Tuettu väite</option><option value="interpretation" ${claim.status==='interpretation'?'selected':''}>Tulkinta</option><option value="open" ${claim.status==='open'?'selected':''}>Avoin</option></select></div>${missing?'<p class="claim-blocker">Julkaisueste: tuetulta väitteeltä puuttuu ihmisen tarkistama lähde.</p>':''}<label>Väite<textarea maxlength="600" rows="3" data-claim-field="text" data-claim-index="${index}">${esc(claim.text)}</textarea></label><fieldset class="claim-source-picker"><legend>Evidenssilähteet</legend>${sourceChoices}</fieldset><label>Huomio<textarea maxlength="800" rows="2" data-claim-field="note" data-claim-index="${index}">${esc(claim.note||'')}</textarea></label><button type="button" class="ghost claim-remove" data-claim-remove="${index}">Poista väite</button></article>`;}).join('');}
function renderEvidenceInteraction(){renderEvidenceSummary();renderSourceReview();renderClaimReview();}
function writeSources(items){els.sources.value=formatSourcesText(items);els.sources.dispatchEvent(new Event('input',{bubbles:true}));}
function writeClaims(items){els.claims.value=formatClaimsText(items);els.claims.dispatchEvent(new Event('input',{bubbles:true}));}
function addSourceFromComposer(){const title=String(els.sourceComposerTitle?.value||'').trim(),url=cleanHttpUrl(els.sourceComposerUrl?.value||''),publisher=String(els.sourceComposerPublisher?.value||'').trim(),date=String(els.sourceComposerDate?.value||'').trim();if(!title||!url){setStatus('Lisää lähteelle otsikko ja kelvollinen http/https-osoite.','err');return;}const sources=parseSourcesText(els.sources.value);if(sources.some(source=>source.url===url)){setStatus('Sama lähde on jo evidenssikerroksessa.','err');return;}sources.push({title,url,publisher,date,origin:'human',verification:'verified'});for(const input of [els.sourceComposerTitle,els.sourceComposerUrl,els.sourceComposerPublisher,els.sourceComposerDate])if(input)input.value='';writeSources(sources);setStatus('✓ Lähde lisätty tarkistetuksi ihmisen lisäämänä.','ok');}
function addClaimCard(){const claims=parseClaimsText(els.claims.value);claims.push({status:'open',text:'Uusi väite',evidence:[],note:''});writeClaims(claims);requestAnimationFrame(()=>els.claimReview?.querySelector(`[data-claim-index="${claims.length-1}"] textarea`)?.focus());}
async function updateSource(index,action){const sources=parseSourcesText(els.sources.value),source=sources[index];if(!source)return;if(action==='remove'){const url=source.url;sources.splice(index,1);const claims=parseClaimsText(els.claims.value).map(claim=>({...claim,evidence:claim.evidence.filter(item=>item!==url)}));els.claims.value=formatClaimsText(claims);}else if(action==='verify'){if(!await window.anomancerDialogs.confirm(`Merkitäänkö “${source.title||source.url}” tarkistetuksi?`,{title:'Vahvista lähteen tarkistus',details:'Vahvista vain, jos olet avannut lähteen ja tarkistanut, että sen sisältö, asiayhteys ja väitteeseen kytkentä pitävät.',confirmLabel:'Merkitse tarkistetuksi'}))return;source.verification='verified';}else source.verification='candidate';writeSources(sources);refreshPreview();updateDirty();}
function updateClaimField(index,field,value){const claims=parseClaimsText(els.claims.value),claim=claims[index];if(!claim)return;if(field==='status')claim.status=['supported','interpretation','open'].includes(value)?value:'open';else if(field==='text')claim.text=String(value||'').trim()||'Uusi väite';else if(field==='note')claim.note=String(value||'').trim();writeClaims(claims);}
function toggleClaimSource(index,url,checked){const claims=parseClaimsText(els.claims.value),claim=claims[index];if(!claim)return;const evidence=new Set(claim.evidence||[]);checked?evidence.add(url):evidence.delete(url);claim.evidence=[...evidence];writeClaims(claims);}
function removeClaim(index){const claims=parseClaimsText(els.claims.value);claims.splice(index,1);writeClaims(claims);}
function refreshPreview(){const p=currentForm(Boolean(state.current?.draft));const words=p.body.trim()?p.body.trim().split(/\s+/).length:0;els.wordCount.textContent=`${words} sanaa · ${Math.max(1,Math.ceil(words/220))} min`;els.descCount.textContent=`${p.description.length} / 220`;els.answerCount.textContent=`${p.answer.length} / 1200`;els.previewBadge.textContent=`${p.pinned?'PINNATTU · ':''}${state.current?.draft===false?'JULKAISTU':'LUONNOS'}`;const coverSrc=p.coverImage?(state.mediaPreviews[p.coverImage]||p.coverImage):'';const cover=p.coverImage?`<figure class="preview-cover"><img src="${escAttr(coverSrc)}" alt="${escAttr(p.coverAlt)}"></figure>`:'';const aud=`<div class="preview-audience">${p.audience.map(id=>`<span>${esc(AUDIENCE_LABELS[id]||id)}</span>`).join('')}<span>${esc(AUDIENCE_DEPTH_LABELS[p.audienceDepth]||'Yleistajuinen')}</span></div>`;const answer=p.answer?`<section class="preview-evidence-answer"><strong>Ydinvastaus</strong><p>${esc(p.answer)}</p></section>`:'';const verified=p.sources.filter(x=>x.verification==='verified').length;const ev=(p.sources.length||p.claims.length)?`<p class="preview-evidence-count">Evidenssikerros · ${verified}/${p.sources.length} lähdettä tarkistettu · ${p.claims.length} väitettä · viitteet ${esc(p.citationMode)}</p>`:'';const previewBody=['inline','both'].includes(p.citationMode)?applyCitationPlacements(p.body,p.citationPlacements):p.body;const charts=(p.visualizations||[]).map(c=>`<figure class="preview-chart"><h3>${esc(c.title)}</h3>${chartSvg(c,true)}${c.caption?`<figcaption>${esc(c.caption)}</figcaption>`:''}</figure>`).join('');els.preview.innerHTML=`<p class="kicker">${esc(CATEGORY_LABELS[p.category]||p.category)}</p>${aud}<h1>${esc(p.title||'Otsikko')}</h1><p class="muted">${esc(p.date||'')}</p>${answer}${cover}${markdown(previewBody||'')}${charts}${ev}`;if(els.citationStatus)els.citationStatus.textContent=`${p.citationPlacements.length} hyväksyttyä inline-sijoitusta · tila: ${p.citationMode}`;updateCoverPreview();renderLiveLink();renderEvidenceInteraction();renderVisualizationReview();}

function setBusy(value){state.busy=value;setEditorLocked(state.editorLocked);for(const element of [els.saveDraft,els.publish,els.del,els.newBtn,els.mobileSave,els.mobilePublish])if(element)element.disabled=value||state.editorLocked||state.workspaceLocked;}
function setEditorLocked(value){state.editorLocked=value;const selectors=['#mobileSaveBtn','#mobilePublishBtn','#lang','#date','#title','#category','#slug','#pinned','#audienceDepth','#description','#translationKey','#coverAlt','#body','#answer','#sources','#claims','#citationPlacements','#visualizations','input[name="citationMode"]','#coverSelectBtn','#coverRemoveBtn','#insertImageBtn','#saveDraftBtn','#publishBtn','#deleteBtn','#newBtn','#agentRunBtn','#agentApplyBtn','#agentMoreBtn','.post-item','.source-review button','.claim-review button','.claim-review select','.claim-review textarea','#sourceComposerTitle','#sourceComposerUrl','#sourceComposerPublisher','#sourceComposerDate','#sourceAddBtn','#claimAddBtn'];for(const selector of selectors)for(const element of $$(selector))element.disabled=value||state.busy||state.workspaceLocked;document.body.classList.toggle('editor-locked',value);document.body.classList.toggle('workspace-artifact-locked',state.workspaceLocked);}
function setWorkspaceContext(detail={}){state.artifact=detail.artifact||state.artifact;state.workspaceLocked=Boolean(state.artifact&&!state.artifact.contentReadable);setEditorLocked(state.editorLocked);if(state.workspaceLocked)setStatus(`◈ ${detail.workspace?.name||'Työtila'} on eristetty. Anomancerin sisältöä ei avattu eikä julkaisukohdetta ole sidottu.`);}
function setSidebarOpen(open){const value=Boolean(open);if(value){setMobileMore(false);setMobilePreview(false);}els.sidebarToggle?.setAttribute('aria-expanded',String(value));const overlays=window.anomancerOverlays;if(overlays){value?overlays.open('dispatch-library',els.sidebarToggle):overlays.close('dispatch-library');return;}els.sidebar?.classList.toggle('is-open',value);document.body.classList.toggle('library-open',value);}
function closeSidebar(){setSidebarOpen(false);}
function updateSidebarLabel(){if(els.sidebarToggle)els.sidebarToggle.textContent=`Lähetykset${state.posts.length?` · ${state.posts.length}`:''}`;}
function syncMobileDock(name){$$('[data-mobile-view]').forEach(button=>{const active=button.dataset.mobileView===name;button.classList.toggle('active',active);button.setAttribute('aria-pressed',String(active));});}
function setMobileMore(open){const value=Boolean(open);if(window.anomancerShell?.setMobileSheet){window.anomancerShell.setMobileSheet(value,document.activeElement);return;}document.body.classList.toggle('mobile-more-open',value);els.mobileMore?.setAttribute('aria-expanded',String(value));if(value)document.body.classList.remove('mobile-preview-open');}
const mobileCommandMedia=window.matchMedia('(max-width:760px)');
function syncMobileCommandHost(){const actions=els.topActions,portal=els.mobileCommandPortal,topbar=$('.topbar');if(!actions||!portal||!topbar)return;if(mobileCommandMedia.matches){if(actions.parentElement!==portal)portal.append(actions);}else{if(actions.parentElement!==topbar)topbar.append(actions);setMobileMore(false);setMobilePreview(false);}}
function setMobilePreview(open){const value=Boolean(open);if(value){setMobileMore(false);closeSidebar();refreshPreview();}const overlays=window.anomancerOverlays;if(overlays){value?overlays.open('editor-preview',els.mobilePreview||document.activeElement):overlays.close('editor-preview');return;}document.body.classList.toggle('mobile-preview-open',value);}
function selectEditorView(name){$$('[data-editor-tab]').forEach(button=>{const active=button.dataset.editorTab===name;button.classList.toggle('active',active);button.setAttribute('aria-selected',String(active));button.tabIndex=active?0:-1;});$$('[data-editor-panel]').forEach(panel=>{const active=panel.dataset.editorPanel===name;panel.classList.toggle('active',active);panel.hidden=!active;});syncMobileDock(name);window.dispatchEvent(new CustomEvent('anomancer:editor-view-change',{detail:{view:name}}));}
window.anomancerOverlays?.register?.('dispatch-library',{element:'#sidebar',backdrop:'#sidebarBackdrop',bodyClass:'library-open',focusSelector:'#sidebarClose',inertSelectors:['#coreShell','.workspace','#mobileDock']});
window.anomancerOverlays?.register?.('editor-preview',{element:'.preview-panel',backdrop:'#mobileUiBackdrop',bodyClass:'mobile-preview-open',focusSelector:'#mobilePreviewClose',inertSelectors:['#coreShell','.workspace-context-bar','#workspaceLocalSidebar','.editor-pane','.editor-resizer','#mobileDock']});

function imageDimensions(file){return new Promise((resolve,reject)=>{const url=URL.createObjectURL(file);const img=new Image();img.onload=()=>{resolve({img,width:img.naturalWidth,height:img.naturalHeight,url})};img.onerror=()=>{URL.revokeObjectURL(url);reject(new Error('Kuvaa ei voitu avata.'))};img.src=url;});}
async function canvasBlob(canvas,type,quality){return await new Promise(resolve=>canvas.toBlob(resolve,type,quality));}
async function prepareImage(file){
  if(!file)throw new Error('Kuva puuttuu.');
  if(!['image/jpeg','image/png','image/webp'].includes(file.type))throw new Error('Tuettu kuvaformaatti: JPG, PNG tai WebP.');
  if(file.size>MAX_SOURCE_BYTES)throw new Error('Alkuperäinen kuva on liian suuri (max 20 Mt).');
  const decoded=await imageDimensions(file);
  try{
    let max=1600,quality=.84,blob=null;
    for(let attempt=0;attempt<5;attempt++){
      const scale=Math.min(1,max/Math.max(decoded.width,decoded.height));
      const w=Math.max(1,Math.round(decoded.width*scale)),h=Math.max(1,Math.round(decoded.height*scale));
      const canvas=document.createElement('canvas');canvas.width=w;canvas.height=h;
      const ctx=canvas.getContext('2d',{alpha:true});ctx.drawImage(decoded.img,0,0,w,h);
      blob=await canvasBlob(canvas,'image/webp',quality);
      if(!blob)blob=await canvasBlob(canvas,'image/jpeg',quality);
      if(blob&&blob.size<=MAX_UPLOAD_BYTES)break;
      max=Math.max(800,Math.round(max*.82));quality=Math.max(.62,quality-.06);
    }
    if(!blob||blob.size>MAX_UPLOAD_BYTES)throw new Error('Kuva ei pienentynyt tarpeeksi. Kokeile pienempää kuvaa.');
    return blob;
  } finally {URL.revokeObjectURL(decoded.url);}
}
function blobDataUrl(blob){return new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(String(r.result));r.onerror=()=>reject(new Error('Kuvan lukeminen epäonnistui.'));r.readAsDataURL(blob);});}
async function uploadImage(file){const blob=await prepareImage(file);const data=await blobDataUrl(blob);const result=await api('/api/admin/content?resource=media',{method:'POST',body:JSON.stringify({data,name:file.name,date:els.date.value})});return {...result,previewData:data};}
function insertAtCursor(text){const el=els.body,start=el.selectionStart??el.value.length,end=el.selectionEnd??start,before=el.value.slice(0,start),after=el.value.slice(end);const prefix=before&&!before.endsWith('\n')?'\n\n':'';const suffix=after&&!after.startsWith('\n')?'\n\n':'';el.value=before+prefix+text+suffix+after;const pos=(before+prefix+text).length;el.focus();el.setSelectionRange(pos,pos);refreshPreview();updateDirty();}
function cleanMdText(s=''){return String(s).replace(/[\[\]\n\r]/g,' ').trim();}
async function chooseCover(file){try{setMediaStatus('Kansikuvaa pienennetään ja lähetetään GitHubiin…');const r=await uploadImage(file);state.mediaPreviews[r.url]=r.previewData;els.coverImage.value=r.url;els.coverAlt.value=els.coverAlt.value.trim()||els.title.value.trim()||cleanMdText(file.name.replace(/\.[^.]+$/,''));setMediaStatus(`✓ Kansikuva tallennettu: ${r.url}`,'ok');refreshPreview();updateDirty();}catch(e){setMediaStatus(`✗ ${e.message}`,'err');}finally{els.coverPicker.value='';}}
async function chooseBodyImage(file){
  const proposed=els.title.value.trim()?`${els.title.value.trim()} – kuva`:cleanMdText(file.name.replace(/\.[^.]+$/,''));
  const imageMeta=await window.anomancerDialogs.form({title:'Kuvan tiedot',message:'Anna kuvalle saavutettava alt-teksti. Kuvateksti on valinnainen.',confirmLabel:'Jatka kuvan lisäämiseen',fields:[{name:'alt',label:'Alt-teksti',value:proposed,required:true,maxLength:300,hint:'Kuvaile olennainen sisältö tiiviisti.'},{name:'caption',label:'Kuvateksti',value:'',maxLength:500,hint:'Näkyvä kuvateksti artikkelissa. Voit jättää tyhjäksi.'}]});if(!imageMeta){els.bodyImagePicker.value='';return;}
  const {alt,caption}=imageMeta;
  try{setMediaStatus('Kuvaa pienennetään ja lähetetään GitHubiin…');const r=await uploadImage(file);state.mediaPreviews[r.url]=r.previewData;const safeAlt=cleanMdText(alt);const safeCaption=String(caption||'').replace(/["\n\r]/g,' ').trim();insertAtCursor(`![${safeAlt}](${r.url}${safeCaption?` "${safeCaption}"`:''})`);setMediaStatus(`✓ Kuva lisätty tekstiin: ${r.url}`,'ok');}catch(e){setMediaStatus(`✗ ${e.message}`,'err');}finally{els.bodyImagePicker.value='';}
}

async function session(){const d=await api('/api/admin/auth?resource=session',{method:'GET'});state.authenticated=d.authenticated;state.csrf=d.csrf||'';els.login.hidden=state.authenticated;els.app.hidden=!state.authenticated;if(state.authenticated){els.repoStatus.textContent=d.github?.configured?`${d.github.repo} · ${d.github.branch}`:'GitHub-yhteys ei ole vielä konfiguroitu';els.repoStatus.className=`repo-status ${d.github?.configured?'ok':''}`;if(d.github?.configured){try{const st=await api('/api/admin/auth?resource=status',{method:'GET'});if(st.github?.fullName){els.repoStatus.textContent=`✓ ${st.github.fullName} · ${st.github.branch}${st.github.private?' · yksityinen':''}`;els.repoStatus.className='repo-status ok';}}catch(e){els.repoStatus.textContent=`GitHub-yhteys: ${e.message}`;els.repoStatus.className='repo-status';}}await loadPosts();window.dispatchEvent(new CustomEvent('anomancer:admin-ready'));}}
async function loadPosts({workspaceId=selectedWorkspaceId()}={}){const requestId=++postsRequestId;postsController?.abort();const controller=new AbortController();postsController=controller;try{const d=await api('/api/admin/content?resource=posts',{method:'GET',workspaceId,signal:controller.signal});if(requestId!==postsRequestId||selectedWorkspaceId()!==workspaceId)return false;if(d.artifact)setWorkspaceContext({workspace:d.workspace,artifact:d.artifact});state.posts=d.posts||[];updateSidebarLabel();renderList();if(state.current?.path){const fresh=state.posts.find(p=>p.path===state.current.path);if(fresh)loadForm(fresh);else loadForm(emptyPost());}else if(state.workspaceLocked)loadForm(emptyPost());return true;}catch(e){if(e.name==='AbortError'||requestId!==postsRequestId||selectedWorkspaceId()!==workspaceId)return false;els.repoStatus.textContent=e.message;els.repoStatus.className='repo-status';return false;}finally{if(requestId===postsRequestId)postsController=null;}}
async function save(draft){if(state.busy||state.editorLocked)return;if(!navigator.onLine){setStatus('✗ Ei verkkoyhteyttä. Luonnosta tai julkaisua ei lähetetty.','err');return;}setBusy(true);try{setStatus(draft?'Tallennetaan luonnosta…':'Lähetetään eetteriin…');const post=currentForm(draft);const d=await api('/api/admin/content?resource=posts',{method:'POST',body:JSON.stringify({path:state.current?.path||'',sha:state.current?.sha||'',post})});const url=`${PUBLIC_ORIGIN}${publicPath(post)}`;await loadPosts();const fresh=state.posts.find(p=>p.path===d.path);if(fresh)loadForm(fresh);const warningText=draft?'':formatEditorialWarnings(d.editorialWarnings);setStatus(draft?'✓ Luonnos tallennettu GitHubiin.':`✓ Lähetyscommitti tehty. Julkinen osoite: ${url} · Vercel vie sen eetteriin automaattisesti.${warningText?`\n${warningText}`:''}`,'ok');}catch(e){if(!await repairEditorialSourceDebt(e))setStatus(`✗ ${formatEditorialIssues(e)}`,'err');}finally{setBusy(false);}}
async function remove(){if(state.busy||state.editorLocked||!state.current?.path)return;const approved=await window.anomancerDialogs.confirm(`Poistetaanko “${state.current.title}”?`,{title:'Poista lähetys',details:'Tämä tekee poistocommitin GitHubiin. Toiminto ei ole pelkkä paikallinen editorimuutos.',confirmLabel:'Poista GitHubista',destructive:true});if(!approved)return;setBusy(true);try{setStatus('Poistetaan…');await api('/api/admin/content?resource=posts',{method:'DELETE',body:JSON.stringify({path:state.current.path,sha:state.current.sha})});state.current=null;state.dirty=false;await loadPosts();loadForm(emptyPost());setStatus('✓ Poistettu GitHubista.','ok');}catch(e){setStatus(`✗ ${e.message}`,'err');}finally{setBusy(false);}}
function publishReview(){const p=currentForm(false);const verified=new Set(p.sources.filter(x=>x.verification==='verified').map(x=>x.url));const pending=p.sources.filter(x=>x.verification!=='verified');const unsupported=p.claims.filter(claim=>claim.status==='supported'&&!claim.evidence.some(url=>verified.has(url)));const errors=[];if(!p.title)errors.push('Otsikko puuttuu.');if(!p.description)errors.push('SEO-kuvaus puuttuu.');if(pending.length)errors.push(`${pending.length} lähdettä odottaa ihmisen tarkistusta.`);if(unsupported.length)errors.push(`${unsupported.length} tuettua väitettä ilman tarkistettua evidenssiä.`);if(p.coverImage&&!p.coverAlt)errors.push('Kansikuvalta puuttuu alt-teksti.');els.publishSummary.innerHTML=`<dl><div><dt>Otsikko</dt><dd>${esc(p.title||'—')}</dd></div><div><dt>Julkinen URL</dt><dd>${esc(PUBLIC_ORIGIN+publicPath(p))}</dd></div><div><dt>Lähteet</dt><dd>${p.sources.length} · ${verified.size} tarkistettu</dd></div><div><dt>Väitteet</dt><dd>${p.claims.length}</dd></div>${p.aliases.length?`<div><dt>Vanhat osoitteet</dt><dd>${p.aliases.map(esc).join(', ')}</dd></div>`:''}</dl>${errors.length?`<div class="publish-errors" role="alert"><strong>Julkaisu ei ole vielä valmis:</strong><ul>${errors.map(error=>`<li>${esc(error)}</li>`).join('')}</ul></div>`:'<p class="publish-ready">✓ Julkaisun pakolliset tarkistukset läpäisty.</p>'}`;els.publishConfirm.disabled=errors.length>0;els.publishDialog.showModal();}

